const rebuildMainBeforeAudio=ShotSchema.rebuildMainPrompt;
ShotSchema.rebuildMainPrompt=function(main,project){rebuildMainBeforeAudio(main,project);if(main.generation?.video_methods||ShotSchema.isStructuredPrompt(main.video_generation?.prompt))return;const lines=[];for(const sub of main.sub_shots||[]){const d=sub.dialogue;if(d&&d.timing_mode!=='natural_within_sub_shot'&&Number.isFinite(d.start_offset_seconds)&&Number.isFinite(d.end_offset_seconds))lines.push(d.start_offset_seconds+'–'+d.end_offset_seconds+'秒：'+characterSpeaker(d.speaker_id)+(d.offscreen?'（画外声音，不出镜）':'')+'：“'+d.text+'”');}if(main.dialogue_timing_mode==='natural_within_sub_shot')main.video_generation.prompt+='\n对白在各自子分镜内按自然语速说完，每句只说一次，不使用精确到小数秒的发声限制，不重复、不重叠；台词仅用于音轨，不生成画面字幕。';if(lines.length)main.video_generation.prompt+='\n对白时间（相对主分镜起点，估算）：\n'+lines.join('\n');if(project.shotScript?.global_audio?.music_tracks?.some(t=>t.generate_separately))main.video_generation.prompt+='\n背景音乐由后期统一添加，本段仅生成对白、连续雨声和必要动作音效，不单独生成背景音乐。';for(const id of main.character_ids||[]){const spec=project.shotScript?.character_reference_specs?.[id];if(spec){const tag=main.picture_inputs.find(p=>p.ref_id===id)?.picture;main.video_generation.prompt+='\n'+(tag||'角色参考图')+' 为同一个角色的四视图设定板，不是多个角色。'+spec.identity+' '+(spec.forbidden||[]).join('；')+'。'+(spec.voice||'');}}main.generation.video_prompt=main.video_generation.prompt;};
const shotsBeforeAudioTiming=shots;
shots=function(){shotsBeforeAudioTiming();if(!data.shotScript?.hierarchical)return;const main=data.shots[si];if(!main?.audio)return;const sub=main.sub_shots[selectedSubShot],d=sub?.dialogue;const status=document.querySelector('#childSaveStatus');if(d&&d.timing_mode!=='natural_within_sub_shot'&&Number.isFinite(d.start_offset_seconds)){const info=document.createElement('p');info.className='subtle';info.textContent='对白估算时间：'+d.start_offset_seconds+'–'+d.end_offset_seconds+' 秒（相对主分镜起点） · 预计说话 '+d.estimated_duration_seconds+' 秒';status.before(info);}const cards=document.querySelectorAll('.shot-script-editor > .card');const audio=document.createElement('details');audio.className='card';audio.style.marginTop='16px';const summary=document.createElement('summary');summary.textContent='对白、音效与配乐时间';audio.append(summary);for(const dialogue of main.audio.dialogues||[]){const p=document.createElement('p');const sub=(main.sub_shots||[]).find(s=>s.sub_shot_id===dialogue.sub_shot_id);p.textContent=(dialogue.timing_mode==='natural_within_sub_shot'?(sub?.start_offset_seconds??0)+'–'+(sub?.end_offset_seconds??main.duration)+' 秒内自然说完':dialogue.start_offset_seconds+'–'+dialogue.end_offset_seconds+' 秒')+' · '+characterSpeaker(dialogue.speaker_id)+(dialogue.offscreen?'（画外）':'')+'：'+dialogue.text;audio.append(p);}for(const fx of main.audio.sfx||[]){const p=document.createElement('p');p.textContent=fx.at_offset_seconds+' 秒 · '+fx.description;audio.append(p);}for(const ambience of main.audio.ambience||[]){const p=document.createElement('p');p.textContent=ambience.start_offset_seconds+'–'+ambience.end_offset_seconds+' 秒 · '+ambience.description;audio.append(p);}for(const bgm of main.audio.bgm_references||[]){const track=data.shotScript.global_audio?.music_tracks?.find(t=>t.track_id===bgm.track_id);const p=document.createElement('p');p.textContent='配乐 '+(track?.name||bgm.track_id)+'：全片 '+bgm.global_start_seconds+'–'+bgm.global_end_seconds+' 秒（后期独立混音）';audio.append(p);}cards[1]?.append(audio);const heading=document.querySelector('#panel .section-head');const policy=document.createElement('p');policy.className='subtle';policy.textContent=data.shotScript.timing_policy||'';heading.after(policy);};render();
